do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-006","project":"qvplwejffhjvxaypmjut","actions":[{"ref":"e0","relation":"editions","key":{"open_library_edition_id":"OL42854732M"},"before":null,"after":{"work_id":282,"title":"De mistmonsters","language":"dut","open_library_edition_id":"OL42854732M","isbn_13":"9789010018052","isbn_10":null,"publisher":"Elsevier"}},{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":282,"language":"nl"},"before":null,"after":{"work_id":282,"language":"nl","bound_author_id":179,"text":"Een Arabische reiziger uit de tiende eeuw trekt met een groep Vikingen naar hun nederzetting. Zijn waarnemingen van een onbekende cultuur vormen het begin van een tocht die steeds verder het gebied van angst en verbeelding binnengaat. Michael Crichton verbindt in deze roman een historische reisbeschrijving met motieven uit Beowulf. Het resultaat krijgt de vorm van een oud verslag, maar blijft fictie. De ontmoeting tussen verschillende werelden staat centraal in het avontuur dat zich ontvouwt.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL46873W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p801872723"],"reference":"work:282","checked_at":"2026-11-02T18:09:00.000Z","note":"De mistmonsters is Dutch Eaters of the Dead1976, not a movie novelisation or an edition of Beowulf. Exact KB1977Elsevier paperback9789010018052; narrator manuscript framing remains fiction. Existing Work282 retained.","supplemental":null},{"type":"original_substantive_source_review","review":"content-review-018.json","sources":["https://openlibrary.org/works/OL46873W","https://data.bibliotheken.nl/id/nbt/p801872723"]},{"type":"cover_front_review","cover_id":13015524,"sha256":"33920e87c8dc824784d96a2e18a13d7827a777d4fc043bc44f03c99b984deef9","reference":"cover-semantic-review-002.json","limitation":"Front tit